// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address baseToken, address nft, uint128 virtualBase, uint128 virtualNft, uint56 changeFee, uint16 feeRate, bytes32 root, bool useStolen, bool payRoyalties) public {
        vm.assume(baseToken != address(0));
        vm.assume(feeRate <= 5000);
        vm.recordLogs();
        c.initialize(baseToken, nft, virtualBase, virtualNft, changeFee, feeRate, root, useStolen, payRoyalties);
        Vm.Log[] memory entries = vm.getRecordedLogs();
        bool emittedMatch;
        for (uint i = 0; i < entries.length; i++) {
            if (entries[i].topics.length > 0 && entries[i].topics[0] == keccak256("Initialize(address,address,uint128,uint128,uint56,uint16,bytes32,bool,bool)")) {
                emittedMatch = abi.decode(entries[i].data, (address,address,uint128,uint128,uint56,uint16,bytes32,bool,bool))._0 == c.baseToken();
                break;
            }
        }
        assertTrue(emittedMatch);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint8 _decimals, uint16 _feeRate) public {
        _feeRate = uint16(bound(_feeRate, 0, 5000));
        vm.assume(_decimals > 4);
        address baseToken = address(new MockERC20(_decimals));
        C c2 = C(payable(address(new C(address(this), address(this), address(this)))));
        c2.initialize(
            baseToken,
            address(0x123),
            100,
            100,
            0,
            _feeRate,
            bytes32(0),
            false,
            false
        );
        bool ok = false;
        try c2.initialize(
            baseToken,
            address(0x123),
            100,
            100,
            0,
            _feeRate,
            bytes32(0),
            false,
            false
        ) { ok = true; } catch { }
        bool isInitialized = c2.initialized();
        assertTrue(isInitialized && !ok);
    }
}

contract MockERC20 {
    uint8 public immutable decimals;
    constructor(uint8 _decimals) { decimals = _decimals; }
}
